{
  "name": "http-status-server",
  "version": "1.0.0",
  "description": "Minimal Node.js HTTP server backed by an HTTP status code lookup table",
  "type": "module",
  "main": "src/server.js",
  "scripts": {
    "start": "node src/server.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

export const STATUS_CODES = Object.freeze({
  100: 'Continue',
  101: 'Switching Protocols',
  102: 'Processing',
  103: 'Early Hints',

  200: 'OK',
  201: 'Created',
  202: 'Accepted',
  203: 'Non-Authoritative Information',
  204: 'No Content',
  205: 'Reset Content',
  206: 'Partial Content',
  207: 'Multi-Status',
  208: 'Already Reported',
  226: 'IM Used',

  300: 'Multiple Choices',
  301: 'Moved Permanently',
  302: 'Found',
  303: 'See Other',
  304: 'Not Modified',
  305: 'Use Proxy',
  307: 'Temporary Redirect',
  308: 'Permanent Redirect',

  400: 'Bad Request',
  401: 'Unauthorized',
  402: 'Payment Required',
  403: 'Forbidden',
  404: 'Not Found',
  405: 'Method Not Allowed',
  406: 'Not Acceptable',
  407: 'Proxy Authentication Required',
  408: 'Request Timeout',
  409: 'Conflict',
  410: 'Gone',
  411: 'Length Required',
  412: 'Precondition Failed',
  413: 'Payload Too Large',
  414: 'URI Too Long',
  415: 'Unsupported Media Type',
  416: 'Range Not Satisfiable',
  417: 'Expectation Failed',
  418: "I'm a Teapot",
  421: 'Misdirected Request',
  422: 'Unprocessable Entity',
  423: 'Locked',
  424: 'Failed Dependency',
  425: 'Too Early',
  426: 'Upgrade Required',
  428: 'Precondition Required',
  429: 'Too Many Requests',
  431: 'Request Header Fields Too Large',
  451: 'Unavailable For Legal Reasons',

  500: 'Internal Server Error',
  501: 'Not Implemented',
  502: 'Bad Gateway',
  503: 'Service Unavailable',
  504: 'Gateway Timeout',
  505: 'HTTP Version Not Supported',
  506: 'Variant Also Negotiates',
  507: 'Insufficient Storage',
  508: 'Loop Detected',
  510: 'Not Extended',
  511: 'Network Authentication Required'
});

export function statusMessage(code) {
  return STATUS_CODES[Number(code)] ?? 'Unknown Status';
}

export function isSuccess(code) {
  const n = Number(code);
  return n >= 200 && n < 300;
}

export function isRedirect(code) {
  const n = Number(code);
  return n >= 300 && n < 400;
}

export function isClientError(code) {
  const n = Number(code);
  return n >= 400 && n < 500;
}

export function isServerError(code) {
  const n = Number(code);
  return n >= 500 && n < 600;
}

export function isError(code) {
  const n = Number(code);
  return n >= 400;
}

export function statusClass(code) {
  return Math.trunc(Number(code) / 100) * 100;
}

import { createServer } from 'node:http';
import { fileURLToPath } from 'node:url';
import { STATUS_CODES, statusMessage } from './status-codes.js';

const DEFAULT_PORT = 3000;

function sendJson(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload)
  });
  res.end(payload);
}

export function createApp() {
  return createServer((req, res) => {
    const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);

    if (req.method === 'GET' && url.pathname === '/') {
      return sendJson(res, 200, {
        name: 'http-status-server',
        endpoints: ['GET /', 'GET /status/:code', 'GET /status-codes']
      });
    }

    if (req.method === 'GET' && url.pathname === '/status-codes') {
      return sendJson(res, 200, STATUS_CODES);
    }

    const match = url.pathname.match(/^\/status\/(\d{3})$/);
    if (req.method === 'GET' && match) {
      const code = Number(match[1]);
      const known = Object.hasOwn(STATUS_CODES, code);
      return sendJson(res, known ? code : 404, {
        code,
        message: statusMessage(code),
        known
      });
    }

    return sendJson(res, 404, {
      code: 404,
      message: statusMessage(404)
    });
  });
}

export function startServer(port = Number(process.env.PORT) || DEFAULT_PORT) {
  const server = createApp();
  server.listen(port, () => {
    console.log(`HTTP server listening on http://localhost:${port}`);
  });
  return server;
}

const isMain = process.argv[1] === fileURLToPath(import.meta.url);
if (isMain) {
  startServer();
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createServer as httpCreateServer } from 'node:http';
import {
  STATUS_CODES,
  statusMessage,
  isSuccess,
  isRedirect,
  isClientError,
  isServerError,
  isError,
  statusClass
} from '../src/status-codes.js';
import { createApp } from '../src/server.js';

test('known status codes map to their reason phrases', () => {
  assert.equal(statusMessage(200), 'OK');
  assert.equal(statusMessage(201), 'Created');
  assert.equal(statusMessage(404), 'Not Found');
  assert.equal(statusMessage(418), "I'm a Teapot");
  assert.equal(statusMessage(500), 'Internal Server Error');
});

test('accepts numeric strings', () => {
  assert.equal(statusMessage('301'), 'Moved Permanently');
});

test('unknown codes fall back to a placeholder', () => {
  assert.equal(statusMessage(299), 'Unknown Status');
});

test('status class helpers partition ranges correctly', () => {
  assert.equal(isSuccess(204), true);
  assert.equal(isSuccess(304), false);
  assert.equal(isRedirect(301), true);
  assert.equal(isClientError(404), true);
  assert.equal(isServerError(503), true);
  assert.equal(isError(399), false);
  assert.equal(isError(400), true);
  assert.equal(statusClass(404), 400);
});

test('lookup table is immutable', () => {
  assert.throws(() => {
    STATUS_CODES[200] = 'Nope';
  }, TypeError);
});

function withServer(fn) {
  return async () => {
    const server = createApp();
    await new Promise((resolve) => server.listen(0, resolve));
    const { port } = server.address();
    try {
      await fn(`http://localhost:${port}`);
    } finally {
      await new Promise((resolve) => server.close(resolve));
    }
  };
}

test(
  'GET /status/404 reports the code and phrase',
  withServer(async (base) => {
    const res = await fetch(`${base}/status/404`);
    assert.equal(res.status, 404);
    assert.deepEqual(await res.json(), {
      code: 404,
      message: 'Not Found',
      known: true
    });
  })
);

test(
  'GET /status/299 falls back to 404 for unknown codes',
  withServer(async (base) => {
    const res = await fetch(`${base}/status/299`);
    assert.equal(res.status, 404);
    const body = await res.json();
    assert.equal(body.known, false);
    assert.equal(body.message, 'Unknown Status');
  })
);

test(
  'GET /status-codes returns the full table',
  withServer(async (base) => {
    const res = await fetch(`${base}/status-codes`);
    assert.equal(res.status, 200);
    const body = await res.json();
    assert.equal(body['200'], 'OK');
    assert.equal(body['500'], 'Internal Server Error');
  })
);

test(
  'unknown route returns a 404 JSON body',
  withServer(async (base) => {
    const res = await fetch(`${base}/does-not-exist`);
    assert.equal(res.status, 404);
    assert.deepEqual(await res.json(), { code: 404, message: 'Not Found' });
  })
);

